import Link from "next/link";
import Image from "next/image";
import { signIn } from "@/auth";
import type { PriceSearchParams } from "@/lib/localized-price";
import { AppearanceControl } from "@/components/appearance-control";
import { Footer } from "@/components/landing/footer";
import { Suspense } from "react";
import PricingPage from "@/components/PricingPage";
import "@/components/pricing/pricing.css";

export const metadata = {
  title: "Plans and pricing",
  description:
    "Compare Mailloop's Free and Premium plans for personalized Gmail outreach, sending limits, and follow-up reminders.",
  alternates: { canonical: "/pricing" },
  robots: { index: true, follow: true },
};

export default function Pricing({
  searchParams,
}: {
  searchParams: PriceSearchParams;
}) {
  async function googleSignIn() {
    "use server";
    await signIn("google", { redirectTo: "/compose" });
  }
  return (
    <div className="pricing-page min-h-dvh bg-[var(--pricing-bg)] text-[var(--pricing-text)] [font-family:var(--font-plus-jakarta),system-ui,sans-serif] text-[15px] leading-[1.55]">
      <div className="pricing-header-wrap max-w-376 my-0 mx-auto [padding-inline:max(32px,_env(safe-area-inset-left))_max(32px,_env(safe-area-inset-right))] border-b border-dotted border-separator [@media(max-width:_639px)]:[padding-inline:max(20px,_env(safe-area-inset-left))_max(20px,_env(safe-area-inset-right))]">
        <nav
          className="pricing-nav flex items-center justify-between gap-5 min-h-23.5 py-5 [@media(max-width:1023px)]:min-h-19 [@media(max-width:1023px)]:py-4 [@media(max-width:639px)]:gap-2"
          aria-label="Main navigation"
        >
          <Link
            className="logo flex shrink-0 items-center min-h-11 gap-4 font-bold text-[32px] [font-family:var(--font-sans)] tracking-[-0.04em] text-[var(--tx)] no-underline [@media(max-width:1023px)]:text-[26px] [@media(max-width:1023px)]:gap-2.5 [@media(max-width:359px)]:text-[24px] [@media(max-width:359px)]:gap-2"
            href="/"
            aria-label="Mailloop home"
            translate="no"
          >
            <span className="pricing-logo-mark size-11.5 rounded-[10px] grid place-items-center shadow-[0_0_28px_var(--color-landing-box-shadow-68)] [@media(max-width:1023px)]:size-9.5">
              <Image
                src="/icon.svg"
                alt=""
                width={36}
                height={36}
                className="size-full"
                unoptimized
              />
            </span>
            <span>mailloop</span>
          </Link>
          <div className="pricing-controls flex items-center gap-7 min-w-0 [@media(max-width:1023px)]:gap-4 [@media(max-width:639px)]:gap-3">
            <nav
              aria-label="Pages"
              className="flex items-center gap-6 [@media(max-width:639px)]:gap-3"
            >
              <Link
                className="inline-flex items-center min-h-11 text-[var(--mu)] no-underline text-[14.5px] font-medium css-hover:text-[var(--tx)] [@media(max-width:639px)]:text-[13px]"
                href="/"
              >
                Home
              </Link>
              <Link
                className="on inline-flex items-center min-h-11 text-[var(--mu)] no-underline text-[14.5px] font-medium css-hover:text-[var(--tx)] [@media(max-width:639px)]:text-[13px] text-[var(--tx)]!"
                href="/pricing"
                aria-current="page"
              >
                Pricing
              </Link>
            </nav>
            <AppearanceControl />
          </div>
        </nav>
      </div>
      <div className="wrap max-w-280 mx-auto px-4 pb-5 pt-4">
        <div className="pricing-shell [background:var(--pricing-bg)] [border:0] rounded-[28px] [padding:18px_clamp(16px,_4vw,_44px)_56px] min-w-0 [scrollbar-color:var(--pricing-muted)_var(--pricing-panel)]">
          <main id="main-content">
            <Suspense fallback={<p role="status">Loading plans…</p>}>
              <PricingPage
                searchParams={searchParams}
                signInAction={googleSignIn}
              />
            </Suspense>
          </main>
          <Footer variant="pricing" />
        </div>
      </div>
    </div>
  );
}
